import {createGeminiClient,GEMINI_MODEL} from './gemini-client.mjs?v=158';
import {reviewWithGemini,tailorWithGemini,prepareClarificationSentences,applyGeminiChanges} from './gemini-tailoring.mjs?v=164';
const esc=value=>String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function setupGeminiTailoring(root,{getSource,getDraft,setDraft,getDescription,getJob=()=>({}),client=createGeminiClient()}){
 const host=document.createElement('section');host.className='gemini-tailoring';host.innerHTML='<h3>Tailor the whole resume with Gemini</h3><p>Review responsibilities, qualifications and accomplishments for this role. Get a tailored summary, supported job keywords in skills and experience, and ordering suggestions for your approval.</p><details data-connect-panel open><summary>Connect your Gemini key</summary><p>Use your own free-tier Google AI Studio project with billing disabled. Your key stays in this tab’s memory and is sent only to Google. App limits do not change Google billing settings.</p><p>Model: Gemini 3.1 Flash-Lite · up to 3 reviews and 15 requests per day in this browser, 5 requests per review. Requests are paced and never retried automatically.</p><details class="gemini-key-privacy"><summary>How your key is protected</summary><p>Your key is kept only in this tab’s memory, not in saved profiles, backups or NextRole servers. Disconnect Gemini or close this tab to clear it. Your browser sends it directly to Google when you request tailoring.</p><p>Using a key in a website requires trusting its code and browser extensions. Use a separate Gemini-only key in a project with billing disabled, and revoke it in Google AI Studio when you no longer need it. Browser usage limits are not a spending guarantee.</p><p><a href="https://ai.google.dev/gemini-api/docs/api-key" target="_blank" rel="noopener noreferrer">Google’s API key security guidance</a></p></details><label>Your Gemini API key<input data-key type="password" autocomplete="off" spellcheck="false" placeholder="Enter privately here" aria-describedby="gemini-key-help"></label><p id="gemini-key-help">Enter your key, confirm Google sharing below, then click Review and tailor. The review button activates your key automatically.</p><button type="button" class="secondary" data-disconnect hidden>Disconnect Gemini</button><p data-connection role="status">Gemini not connected.</p><label class="autofill-confirm"><input type="checkbox" data-consent> I agree to send my resume, this job description and any approved clarification answers to Google Gemini. I have checked that my project uses the free tier without billing.</label><p>Google may use free-tier inputs to improve its products. <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noopener noreferrer">Google’s free-tier terms</a></p></details><p data-usage></p><div class="permission-actions"><button type="button" class="find-jobs" data-review>Review and tailor with Gemini</button><button type="button" class="secondary" data-cancel hidden>Cancel review</button></div><p data-progress role="status"></p><div data-diagnostics hidden><button type="button" class="secondary" data-check>Test Gemini JSON connection (no resume)</button><p>This sends a small sample to Google using the same JSON response mode as tailoring. Your resume and job description are not included. It uses one request from your daily limit.</p><p data-check-status role="status"></p></div><div data-interview></div><div data-results></div>';
 root.querySelector('[data-description]').parentElement.after(host);const q=s=>host.querySelector(s),cached=new Map(),applied=new Map();let controller=null,session=null,active=null,data=null,approvedFacts=[],busy=false,sequence=0;
 const current=()=>JSON.stringify({resume:getSource(),description:getDescription(),job:getJob()});
 async function usage(){try{const u=await client.usage();q('[data-usage]').textContent=u?u.reviewsLeft+' reviews and '+u.requestsLeft+' requests left today in this browser.':'';}catch(error){q('[data-usage]').textContent=error.message;}}
 function setBusy(value){busy=value;q('[data-review]').disabled=value;q('[data-check]').disabled=value;q('[data-key]').disabled=value;q('[data-cancel]').hidden=!value;}
 function reset(){sequence++;controller?.abort();controller=null;session=null;active=null;data=null;approvedFacts=[];q('[data-interview]').replaceChildren();q('[data-results]').replaceChildren();q('[data-diagnostics]').hidden=true;q('[data-check-status]').textContent='';setBusy(false);}
 const stale=(id,snapshot)=>id!==sequence||controller?.signal.aborted||snapshot!==current();
 async function connectEnteredKey(){const field=q('[data-key]');if(!field.value.trim())return false;try{await client.connect(field.value);field.value='';cached.clear();applied.clear();q('[data-connection]').textContent='Key ready for this tab. It has not been tested or saved.';q('[data-disconnect]').hidden=false;return true;}catch(error){q('[data-connect-panel]').open=true;q('[data-connection]').textContent=error.message;throw error;}}
 q('[data-disconnect]').onclick=()=>{reset();client.disconnect();cached.clear();applied.clear();q('[data-key]').value='';q('[data-consent]').checked=false;q('[data-disconnect]').hidden=true;q('[data-connection]').textContent='Gemini disconnected. The key and cached reviews were cleared from memory.';usage();};
 q('[data-consent]').onchange=()=>{if(!q('[data-consent]').checked){reset();q('[data-progress]').textContent='Google sharing stopped. Your draft is unchanged.';}};
 q('[data-cancel]').onclick=()=>{reset();q('[data-progress]').textContent='Review cancelled. Your draft is unchanged.';usage();};
 function progress(text){q('[data-progress]').textContent=text;}
 q('[data-check]').onclick=async()=>{if(busy)return;setBusy(true);const out=q('[data-check-status]');controller=new AbortController();out.textContent='Checking your key, model and JSON response mode. Your resume is not included…';try{await client.checkConnection({signal:controller.signal,onProgress:text=>{out.textContent=text;}});out.textContent='JSON connection test passed. Google accepted your key, model and tailoring response mode. You can now try Review and tailor. Your draft was not changed.';}catch(error){out.textContent='The JSON connection test failed. Your resume and job description were not sent. '+error.message;}finally{setBusy(false);await usage();}};
 function renderEvidence(result){const details=document.createElement('details');details.className='gemini-requirements';const title=document.createElement('summary');title.textContent='Role requirements and gaps';details.append(title);const note=document.createElement('p');note.textContent='A focused evidence review, not an exhaustive eligibility assessment. Missing qualifications are not added to the resume.';details.append(note);for(const r of result.requirements){const card=document.createElement('article');card.className='local-evidence';const h=document.createElement('strong');h.textContent=({'supported':'Supported','partial':'Partially supported','missing':'Missing','unclear':'Unclear'}[r.status]||'Unclear')+' · '+r.requirement;card.append(h);const why=document.createElement('details'),label=document.createElement('summary');label.textContent='Why this assessment?';why.append(label);for(const [name,quote] of [['Job',r.job_quote],['Resume',r.resume_quote]])if(quote){const p=document.createElement('p');p.textContent=name+': '+quote;why.append(p);}card.append(why);details.append(card);}return details;}
 function renderChanges(result,snapshot,draftSnapshot,facts){data=result;active={snapshot,draftSnapshot};const target=q('[data-results]');target.replaceChildren();q('[data-interview]').replaceChildren();
  const changes=[...result.edits,...(result.summary?[result.summary]:[]),...result.orderings.map(o=>({...o,replacement:o.order.map(id=>{if(o.group.kind==='projects')return result.parsed.lines[o.group.items[o.group.block_ids.indexOf(id)][0]];return result.parsed.blocks.find(b=>b.id===id)?.text||id;}).join('\n'),original:o.group.block_ids.map(id=>o.group.kind==='projects'?result.parsed.lines[o.group.items[o.group.block_ids.indexOf(id)][0]]:result.parsed.blocks.find(b=>b.id===id)?.text||id).join('\n'),kind:'ordering'}))];
  target.append(renderEvidence(result));if(!changes.length&&!facts.length){progress('No meaningful changes passed the checks. Your draft is unchanged.');return;}
  const intro=document.createElement('p');intro.textContent='Select the changes you want. Applying them replaces the download draft; your original matching resume stays unchanged.';target.append(intro);
  if(facts.length){const note=document.createElement('p');note.textContent='Your approved sentences are already saved with their original accomplishments:';target.append(note);for(const fact of facts){const item=document.createElement('p');item.className='change-text';item.textContent=fact.text;target.append(item);}}if(!changes.length){progress('Your approved answers are in the draft. No additional wording changes passed the checks.');return;}
  const cards=document.createElement('div');cards.innerHTML=changes.map(change=>'<article class="gemini-change"><label><input type="checkbox" data-change="'+esc(change.id)+'"> '+({'wording':'Wording','skills':'Skills and job keywords','summary':'Summary','ordering':'Ordering'}[change.kind]||'Wording')+'</label><strong>Before</strong><p class="change-text">'+esc(change.original)+'</p><strong>After</strong><p class="change-text">'+esc(change.replacement)+'</p><details><summary>Why this change?</summary><p>'+esc(change.rationale||'Bring role-relevant evidence forward.')+'</p>'+(change.keyword_evidence?.length?'<p>Job keywords: '+change.keyword_evidence.map(k=>esc(k.term)).join(', ')+'</p>':'')+(change.job_quote?'<p>Job: '+esc(change.job_quote)+'</p>':'')+'</details></article>').join('');target.append(cards);
  const apply=document.createElement('button'),all=document.createElement('button'),clear=document.createElement('button');apply.type=all.type=clear.type='button';apply.className='find-jobs';all.className=clear.className='secondary';apply.textContent=facts.length&&!changes.length?'Apply approved evidence':'Apply selected changes';all.textContent='Apply all compatible changes';clear.textContent='Clear selection';
  function applySelection(ids){try{if(current()!==snapshot||getDraft()!==draftSnapshot)throw Error('The resume, job or draft changed. Request a fresh review before applying.');if(!ids.length)throw Error('Select a wording, summary or ordering change first. Approved answers are already saved in your draft.');const value=applyGeminiChanges(result.source,result,ids);setDraft(value);applied.set(snapshot,value);target.replaceChildren();progress('Your approved tailored draft is ready. Review its content and page count before downloading.');}catch(error){progress(error.message);}}
  apply.onclick=()=>applySelection([...cards.querySelectorAll('[data-change]:checked')].map(input=>input.dataset.change));
  all.onclick=()=>{const ids=changes.map(c=>c.id).filter(id=>{const edit=result.edits.find(e=>e.id===id);return !result.summary||!edit||!edit.indices.some(i=>result.summary.indices.includes(i));});for(const field of cards.querySelectorAll('[data-change]'))field.checked=ids.includes(field.dataset.change);applySelection(ids);};clear.onclick=()=>{for(const field of cards.querySelectorAll('[data-change]'))field.checked=false;};
  const actions=document.createElement('div');actions.className='permission-actions';actions.append(apply,all,clear);target.append(actions);if(result.advice.length){const notes=document.createElement('details'),label=document.createElement('summary');label.textContent='Suggestions to strengthen your evidence';notes.append(label);for(const advice of result.advice){const p=document.createElement('p');p.textContent=advice;notes.append(p);}target.append(notes);}
 }
 async function finish(id,snapshot,draftSnapshot,answers){setBusy(true);try{if(stale(id,snapshot))throw Error('The resume or role changed. Start a fresh review.');const working=applyGeminiChanges(session.source,{edits:answers,orderings:[],summary:null},answers.map(a=>a.id));approvedFacts=answers.map(a=>({text:a.replacement}));if(approvedFacts.length){if(getDraft()!==draftSnapshot)throw Error('The draft changed. Start a fresh review before adding answers.');setDraft(working);draftSnapshot=working;q('[data-interview]').innerHTML='<h4>Answers added to your draft</h4>'+approvedFacts.map(a=>'<p class="change-text">'+esc(a.text)+'</p>').join('');progress('Your approved answers are saved in the draft. Reviewing role-specific wording…');}const result=await tailorWithGemini(client,session,working,{signal:controller.signal,onProgress:progress});if(stale(id,snapshot))return;cached.set(snapshot,{result,draftSnapshot,facts:approvedFacts});if(cached.size>4)cached.delete(cached.keys().next().value);renderChanges(result,snapshot,draftSnapshot,approvedFacts);if(result.edits.length||result.summary||result.orderings.length)progress(approvedFacts.length?'Your answers are saved. Review the proposed AI wording changes below; those have not been applied.':'Review the proposed changes below. Nothing has been applied yet.');}
  catch(error){if(id===sequence){progress(approvedFacts.length?'Your approved answers remain saved in the draft. No AI wording changes were applied. '+error.message.replace(/Your draft (?:is unchanged|was not changed)[^.]*\./g,''):error.message+' Your draft was not changed.');q('[data-diagnostics]').hidden=!client.isConnected();}}finally{if(id===sequence){setBusy(false);await usage();}}
 }
 async function prepareAnswers(id,snapshot,draftSnapshot,answers){
  if(!answers.length)return finish(id,snapshot,draftSnapshot,[]);
  setBusy(true);try{const proposed=await prepareClarificationSentences(client,session,answers,{signal:controller.signal,onProgress:progress});if(stale(id,snapshot))return;if(getDraft()!==draftSnapshot)throw Error('The draft changed. Start a fresh review.');session.answersPrepared=true;
   const target=q('[data-interview]');target.replaceChildren();const title=document.createElement('h4');title.textContent='Review your answers as resume sentences';target.append(title);
   for(const item of proposed){const card=document.createElement('fieldset');card.innerHTML='<legend>Proposed accomplishment</legend><p><strong>Your answer:</strong> '+esc(item.answer)+'</p><p><strong>Resume wording:</strong> '+esc(item.replacement)+'</p><label><input type="checkbox" data-sentence="'+esc(item.id)+'"> I confirm the wording and technology names; include this sentence</label>';target.append(card);}
   for(const item of proposed.rejected||[]){const note=document.createElement('p');note.textContent='Answer not added: '+item.answer+' — '+item.reason;target.append(note);if(item.replacement){const preview=document.createElement('p');preview.className='change-text';preview.textContent='Proposed wording (not saved): '+item.replacement;target.append(preview);}}
   if(!proposed.length){progress('Your answers are shown below, but no sentence passed the checks. No changes were saved.');return;}
   const save=document.createElement('button');save.type='button';save.className='find-jobs';save.textContent='Add approved sentences and continue tailoring';save.onclick=()=>{const ids=[...target.querySelectorAll('[data-sentence]:checked')].map(x=>x.dataset.sentence);if(!ids.length){progress('Select the sentences you want included first.');return;}save.disabled=true;finish(id,snapshot,draftSnapshot,proposed.filter(p=>ids.includes(p.id)));};target.append(save);progress('Review the complete wording and select the sentences to add. Nothing has been added yet.');
  }catch(error){if(id===sequence)progress(error.message+' No answer fragments were added. Start a fresh review to try again.');}finally{if(id===sequence){setBusy(false);await usage();}}
 }
 function interview(id,snapshot,draftSnapshot){const target=q('[data-interview]');target.innerHTML='<h4>A few missing facts</h4><p>Answer only what you can verify. Leave unknown answers blank; no metrics or qualifications will be invented.</p>'+session.review.questions.map((question,i)=>'<fieldset><legend>'+esc(question.question)+'</legend><p>'+esc(question.original)+'</p><label>Your answer (optional)<textarea data-answer="'+i+'" maxlength="500" rows="2"></textarea></label><label><input type="checkbox" data-answer-approved="'+i+'"> I confirm this fact and want Gemini to turn it into resume wording for my approval.</label></fieldset>').join('')+'<button type="button" class="find-jobs" data-continue>Prepare resume sentences</button> <button type="button" class="secondary" data-skip>Continue without additions</button>';
  target.querySelector('[data-continue]').onclick=()=>{for(const field of target.querySelectorAll('[data-answer]')){const i=field.dataset.answer;if(field.value.trim()&&!target.querySelector('[data-answer-approved="'+i+'"]').checked){progress('Confirm each answer you want added, or clear it before continuing.');return;}}for(const b of target.querySelectorAll('button'))b.disabled=true;const answers=session.review.questions.map((question,i)=>({block_id:question.block_id,text:target.querySelector('[data-answer="'+i+'"]').value.trim(),approved:target.querySelector('[data-answer-approved="'+i+'"]').checked})).filter(a=>a.approved&&a.text);prepareAnswers(id,snapshot,draftSnapshot,answers);};target.querySelector('[data-skip]').onclick=()=>{for(const b of target.querySelectorAll('button'))b.disabled=true;finish(id,snapshot,draftSnapshot,[]);};
 }
 q('[data-review]').onclick=async()=>{if(busy)return;reset();const id=sequence,snapshot=current(),draftSnapshot=getDraft();try{setBusy(true);if(!q('[data-consent]').checked)throw Error('Confirm Google sharing and your free-tier project before continuing.');await connectEnteredKey();if(!client.isConnected())throw Error('Enter your Gemini API key above, then click Review and tailor.');if(applied.get(snapshot)===getDraft()){progress('These approved changes are already in your draft. No Gemini request was made.');return;}const saved=cached.get(snapshot);if(saved&&saved.draftSnapshot===draftSnapshot){renderChanges(saved.result,snapshot,draftSnapshot,saved.facts);progress('Showing the cached review. No Gemini request was made.');return;}if(!q('[data-consent]').checked)throw Error('Confirm Google sharing and your free-tier project before continuing.');controller=new AbortController();setBusy(true);progress('Reviewing your whole resume against this role…');session=await reviewWithGemini(client,draftSnapshot,{...getJob(),description:getDescription()},{signal:controller.signal,onProgress:progress});if(stale(id,snapshot))return;q('[data-connection]').textContent='Gemini responded successfully for this review.';q('[data-connect-panel]').open=false;if(session.review.questions.length){interview(id,snapshot,draftSnapshot);setBusy(false);progress('Only missing evidence is requested. Approve answers before sending them to Gemini.');}else await finish(id,snapshot,draftSnapshot,[]);}
  catch(error){if(id===sequence){progress(error.message);q('[data-diagnostics]').hidden=!client.isConnected();}}finally{if(id===sequence){setBusy(false);await usage();}}
 };
 root.addEventListener('input',event=>{if(event.target.matches('[data-description],[data-draft]')){reset();q('[data-progress]').textContent='The resume or role changed. Request a fresh review.';}});
 return {refresh(){reset();q('[data-consent]').checked=false;q('[data-progress]').textContent='';usage();},stop(){reset();q('[data-key]').value='';},disconnect(){reset();client.disconnect();cached.clear();applied.clear();}};
}
